const topics = [
  {
    topic: "How Deep Breathing Deactivates Chronic Pain Signals in the Brain",
    category: "Neuroscience & Pain Relief",
    keywords: ["deep breathing for pain", "parasympathetic nervous system", "chronic pain meditation"]
  },
  {
    topic: "Overcoming Hopelessness: What to Do When Doctors Say Nothing More Can Be Done",
    category: "Mindset & Resilience",
    keywords: ["healing mindset", "overcoming despair", "Dr V Three Pillars"]
  },
  {
    topic: "Guided Sleep Journeys: How to Break Nighttime Pain Cycles and Insomnia",
    category: "Sleep & Restorative Healing",
    keywords: ["sleep meditation for chronic pain", "healing insomnia naturally", "restorative sleep"]
  },
  {
    topic: "Rewiring the Subconscious Mind: Breaking Free from the Trauma of Immobility",
    category: "Subconscious Reprogramming",
    keywords: ["subconscious reprogramming", "emotional recovery", "mind over illness"]
  },
  {
    topic: "Faith as a Biological Catalyst: The Placebo Effect Taken to Its Clinical Extreme",
    category: "Faith & Biological Recovery",
    keywords: ["placebo effect healing", "power of belief in medicine", "faith and health"]
  }
];

const selected = topics[Math.floor(Math.random() * topics.length)];

const fullPrompt = "You are Dr. V — a medical doctor and author of Self-Healing: The Road to Recovery and The Three Pillars of Self-Healing.\n" +
  "You survived an L5 spinal fracture, 2 failed surgeries, and were told you would remain paralyzed in a wheelchair.\n" +
  "Through Faith, Gratitude, and Meditation, you broke the pain loop and healed.\n\n" +
  "Write an authoritative 1500-word article on:\n" +
  "Topic: " + selected.topic + "\n" +
  "Category: " + selected.category + "\n" +
  "Keywords: " + selected.keywords.join(", ") + "\n\n" +
  "Output strictly valid raw JSON without markdown formatting:\n" +
  "{\n" +
  '  \"title\": \"Title under 65 chars\",\n' +
  '  \"slug\": \"clean-english-url-slug\",\n' +
  '  \"category\": \"' + selected.category + '\",\n' +
  '  \"meta_title\": \"SEO title\",\n' +
  '  \"meta_description\": \"SEO snippet\",\n' +
  '  \"excerpt\": \"2-sentence summary\",\n' +
  '  \"content\": \"<p>Article in semantic HTML using h2, h3, p, blockquote, ul, li...</p>\",\n' +
  '  \"faq_json\": [{\"q\": \"Question 1?\", \"a\": \"Answer 1\"}]\n' +
  "}";

return [{
  json: {
    ...selected,
    fullPrompt: fullPrompt
  }
}];

let text = '';
if ($input.item.json.output && $input.item.json.output[0] && $input.item.json.output[0].content) {
  text = $input.item.json.output[0].content[0].text || '';
} else if ($input.item.json.text) {
  text = $input.item.json.text;
} else if (typeof $input.item.json === 'string') {
  text = $input.item.json;
} else {
  text = JSON.stringify($input.item.json);
}

text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {};
}

let original = {};
try {
  original = $('Select High-Intent Healing Topic').item.json || {};
} catch (e) {}

const title = parsed.title || 'Healing Through Awareness: The Three Pillars Method';
const category = parsed.category || original.category || 'Healing & Mindfulness';
const slug = parsed.slug || ('healing-article-' + Date.now());
const meta_title = parsed.meta_title || (title + ' | Dr. V Healing');
const meta_description = parsed.meta_description || parsed.excerpt || 'Learn how to heal using Faith, Gratitude, and Meditation.';
const excerpt = parsed.excerpt || meta_description;
const content = parsed.content || '<p>Recovery begins in the mind before it manifests in tissue.</p>';
const faq_json = parsed.faq_json || [];

return {
  json: {
    title: title,
    slug: slug,
    category: category,
    meta_title: meta_title,
    meta_description: meta_description,
    excerpt: excerpt,
    content: content,
    faq_json: faq_json
  }
};

